  currentInvoiceId = id;
  invoiceItemCounter = 0;
  document.getElementById('invoice-editor-title').textContent = 'Invoice ' + (inv.invoiceNumber || '');
  document.getElementById('btn-delete-invoice')?.classList.remove('hidden');
