function parseCsv(text) {
  const rows = [];
  let row = [], cell = '', i = 0, inQuotes = false;
  const s = text.replace(/^\uFEFF/, '');
  while (i < s.length) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') { cell += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      cell += c; i++; continue;
    }
    if (c === '"') { inQuotes = true; i++; continue; }
    if (c === ',') { row.push(cell); cell = ''; i++; continue; }
    if (c === '\n' || c === '\r') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some(x => String(x).trim() !== '')) rows.push(row);
      row = []; i++; continue;
    }
    cell += c; i++;
  }
  row.push(cell);
  if (row.some(x => String(x).trim() !== '')) rows.push(row);
  return rows;
}

function normalizeHeader(h) {
  return String(h || '').trim().toLowerCase().replace(/[_\s]+/g, ' ');
}

function importProductsFromCsv(file) {
  const reader = new FileReader();
  reader.onload = (ev) => {
    try {
      const rows = parseCsv(ev.target.result);
      if (rows.length < 2) {
        alert('Spreadsheet is empty or has no data rows.');
        return;
      }
      const headers = rows[0].map(normalizeHeader);
      const col = (...names) => {
        for (const n of names) {
          const idx = headers.indexOf(n);
          if (idx >= 0) return idx;
        }
        return -1;
      };
      const iSku = col('sku');
      const iName = col('name', 'equipment', 'product', 'item');
      const iCat = col('category');
      const iBrand = col('brand');
      const iDesc = col('description', 'description / specs', 'specs');
      const iFeat = col('features', 'key features');
      const iPrice = col('price');
      const iCur = col('currency');
      const iStock = col('stock', 'stock qty', 'qty');
      const iLow = col('low stock', 'low stock alert');
      const iActive = col('active');

      if (iSku < 0 || iName < 0 || iPrice < 0) {
        alert('Spreadsheet must have at least: SKU, Name, Price\n\nDownload the template for the correct format.');
        return;
      }

      let added = 0, updated = 0, skipped = 0;
      if (!data.categories) data.categories = [];

      for (let r = 1; r < rows.length; r++) {
        const row = rows[r];
        const sku = String(row[iSku] || '').trim();
        const name = String(row[iName] || '').trim();
        if (!sku || !name) { skipped++; continue; }

        const price = parseFloat(String(row[iPrice] || '0').replace(/,/g, '')) || 0;
        let currency = iCur >= 0 ? String(row[iCur] || 'USD').trim().toUpperCase() : 'USD';
        if (!['USD', 'EUR', 'NGN'].includes(currency)) currency = 'USD';
        const category = iCat >= 0 ? String(row[iCat] || 'General').trim() : 'General';
        const brand = iBrand >= 0 ? String(row[iBrand] || '').trim() : '';
        const description = iDesc >= 0 ? String(row[iDesc] || '').trim() : '';
        const features = iFeat >= 0 ? String(row[iFeat] || '').trim() : '';
        const stock = iStock >= 0 ? parseInt(row[iStock], 10) || 0 : 0;
        const lowStock = iLow >= 0 ? parseInt(row[iLow], 10) || 0 : 2;
        let active = true;
        if (iActive >= 0) {
          const a = String(row[iActive] || 'yes').trim().toLowerCase();
          active = !(a === 'no' || a === 'false' || a === '0' || a === 'inactive');
        }

        if (category && !data.categories.some(c => c.toLowerCase() === category.toLowerCase())) {
          data.categories.push(category);
        }

        const existing = data.products.find(p => p.sku.toLowerCase() === sku.toLowerCase());
        if (existing) {
          existing.name = name;
          existing.category = category;
          existing.brand = brand;
          existing.description = description;
          existing.features = features;
          existing.price = price;
          existing.currency = currency;
          existing.stock = stock;
          existing.lowStock = lowStock;
          existing.active = active;
          updated++;
        } else {
          data.products.push({
            id: uid(),
            sku, name, category, brand, description, features,
            price, currency, stock, lowStock, active, image: ''
          });
          added++;
        }
      }

      data.categories.sort();
      saveData();
      renderProducts();
      renderDashboard();
      if (typeof populateCategorySelect === 'function') populateCategorySelect();
      alert('Import complete.\n\nAdded: ' + added + '\nUpdated: ' + updated + '\nSkipped: ' + skipped);
    } catch (err) {
      console.error(err);
      alert('Could not read the spreadsheet. Save as CSV (UTF-8) from Excel and try again.');
    }
  };
  reader.readAsText(file);
}

function onImportProductsFile(e) {
  const file = e.target.files && e.target.files[0];
  if (!file) return;
  const name = file.name.toLowerCase();
  if (name.endsWith('.xlsx') || name.endsWith('.xls')) {
    alert('Please save your Excel file as CSV first:\n\nFile → Save As → CSV (Comma delimited)\n\nThen import the .csv file.');
    e.target.value = '';
    return;
  }
  importProductsFromCsv(file);
  e.target.value = '';
}

function exportQuotesExcel() {
  const rows = [
    ['Quote #', 'Client', 'Title', 'Status', 'Discount %', 'Subtotal NGN', 'Total NGN', 'Valid Until', 'Created', 'Items']
  ];
  data.quotes.forEach(q => {
    const client = getClient(q.clientId);
    const itemsSummary = (q.items || []).map(i => `${i.qty}x ${i.name || i.sku}`).join('; ');
    rows.push([
      q.quoteNumber,
      client ? client.name : '',
      q.title,
      q.status,
      q.discount || 0,
      q.subtotalNGN,
      q.totalNGN,
      q.validUntil || '',
      q.createdAt ? new Date(q.createdAt).toLocaleDateString() : '',
      itemsSummary
    ]);
  });
  downloadCsv(`medicano-quotes-${new Date().toISOString().slice(0, 10)}.csv`, rows);
  alert('Quotes exported. Open the CSV file in Excel.');
}

function emailQuote() {
  // Build summary and open mail client; user can attach the PDF after Print/Save
  const clientId = document.getElementById('quote-client')?.value;
  const client = getClient(clientId);
  const title = document.getElementById('quote-title')?.value || 'Quotation';
  const total = document.getElementById('quote-total')?.textContent || '';
  const quoteNum = currentQuoteId
    ? (data.quotes.find(q => q.id === currentQuoteId) || {}).quoteNumber || 'DRAFT'
    : 'DRAFT';
  const co = data.company;

  let itemsText = '';
  document.querySelectorAll('#quote-items-list .line-card').forEach(row => {
    const productId = row.querySelector('.qi-product')?.value;
    if (!productId) return;
    const p = getProduct(productId);
    const qty = row.querySelector('.qi-qty')?.value || 1;
    itemsText += `- ${qty} x ${p.name} (${p.sku})\n`;
  });

  const subject = encodeURIComponent(`Quotation ${quoteNum} — ${co.name}`);
  const body = encodeURIComponent(
    `Dear ${client ? (client.contact || client.name) : 'Sir/Madam'},\n\n` +
    `Please find our quotation details below.\n\n` +
    `Quote #: ${quoteNum}\n` +
    `Project: ${title}\n` +
    `Client: ${client ? client.name : '—'}\n` +
    `Total: ${total}\n\n` +
    `Items:\n${itemsText || '(see attached PDF)'}\n\n` +
    `Please reply to confirm, or find the full PDF attached.\n\n` +
    `Kind regards,\n${co.name}\n${co.phone1} | ${co.phone2}\n${co.email}\n${co.address}`
  );

  const to = client && client.email ? client.email : '';
  const mailto = `mailto:${to}?subject=${subject}&body=${body}`;

  // Try Web Share on mobile first
  if (navigator.share) {
    navigator.share({
      title: `Quotation ${quoteNum}`,
      text: decodeURIComponent(body),
    }).catch(() => {
      window.location.href = mailto;
    });
  } else {
    window.location.href = mailto;
  }

  setTimeout(() => {
    alert('Mail app opened.\n\nTip: Use “Print / PDF” first, save the PDF, then attach it to the email.');
  }, 400);
}

function importData(e) {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    try {
      const imported = JSON.parse(ev.target.result);
      if (!imported.products || !imported.clients) throw new Error('Invalid file');
      if (confirm('This will replace ALL current data. Continue?')) {
        data = imported;
        saveData();
        alert('Data imported successfully.');
        navigate('dashboard');
      }
    } catch (err) {
      alert('Invalid backup file.');
    }
  };
  reader.readAsText(file);
  e.target.value = '';
}

function resetData() {
  data = JSON.parse(JSON.stringify(DEFAULT_DATA));
  saveData();
  navigate('dashboard');
  alert('All data has been reset to defaults.');
}

// -------------------- Client Presentation --------------------
function populatePresQuoteSelect() {
  const sel = document.getElementById('pres-from-quote');
  if (!sel) return;
  const cur = sel.value;
  const quotes = (data.quotes || []).slice().sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
  sel.innerHTML = '<option value="">— Select a saved quote —</option>' +
    quotes.map(q => {
      const c = getClient(q.clientId);
      const label = (q.quoteNumber || 'Quote') + ' — ' + (c ? c.name : 'Client') + ' — ' + (q.title || '');
      return '<option value="' + q.id + '">' + escHtml(label) + '</option>';
    }).join('');
  if (cur) sel.value = cur;
}

function applyQuoteToPresentation() {
  const id = document.getElementById('pres-from-quote')?.value;
  if (!id) { alert('Select a quotation first.'); return; }
  const q = (data.quotes || []).find(x => x.id === id);
  if (!q) { alert('Quote not found.'); return; }
  const client = getClient(q.clientId);
  if (client && document.getElementById('pres-client')) {
    document.getElementById('pres-client').value = client.name || '';
  }
  if (q.title && document.getElementById('pres-title')) {
    document.getElementById('pres-title').value = q.title;
  }
  // Store quote items for generatePresentation
  window._presQuoteItems = (q.items || []).map(it => {
    const p = it.productId ? getProduct(it.productId) : null;
    const unit = it.unitNGN != null ? it.unitNGN : (it.unitNgn != null ? it.unitNgn : (p ? toNGN(p.price, p.currency) : 0));
    const qty = it.qty || 1;
    return {
      id: it.productId || ('custom-' + (it.name || 'item') + '-' + Math.random().toString(36).slice(2, 6)),
      productId: it.productId || '',
      name: it.name || (p ? p.name : 'Item'),
      sku: it.sku || (p ? p.sku : ''),
      category: (p && p.category) || 'Equipment',
      description: (p && p.description) || '',
      features: (p && p.features) || '',
      image: (p && p.image) || '',
      price: unit,
      currency: 'NGN',
      qty: qty,
      fromQuote: true
    };
  });
  // Also check catalog products that match
  const picker = document.getElementById('pres-picker');
  if (picker) {
    picker.querySelectorAll('.pres-check').forEach(cb => { cb.checked = false; });
    (q.items || []).forEach(it => {
      if (!it.productId) return;
      const cb = picker.querySelector('.pres-check[value="' + it.productId + '"]');
      if (cb) cb.checked = true;
    });
  }
  alert('Loaded ' + (window._presQuoteItems || []).length + ' item(s) from ' + (q.quoteNumber || 'quote') + '. Generate PDF when ready.');
}

function renderPresPicker() {
  populatePresQuoteSelect();
  const search = (document.getElementById('pres-search')?.value || '').toLowerCase();
  const container = document.getElementById('pres-picker');
  if (!container) return;

  const list = data.products.filter(p => p.active).filter(p =>
    !search ||
    (p.name || '').toLowerCase().includes(search) ||
    (p.sku || '').toLowerCase().includes(search) ||
    (p.category || '').toLowerCase().includes(search) ||
    (p.brand || '').toLowerCase().includes(search) ||
    (p.description || '').toLowerCase().includes(search)
  );

  if (list.length === 0) {
    container.innerHTML = '<p class="p-4 text-slate-400 text-center">No equipment found</p>';
    return;
  }

  // Payment-style select rows: all inventory details, no images / no icons
  // Price: Naira only, bold, same size as name, bottom-right of card
  container.innerHTML = list.map(p => {
    const ngnStr = formatNGN(toNGN(p.price, p.currency));
    const stock = Number(p.stock) || 0;
    const low = stock <= (Number(p.lowStock) || 1);
    const meta = [
      p.sku ? `SKU ${p.sku}` : null,
      p.category || null,
      p.brand || null,
      `Stock ${stock}${low ? ' · low' : ''}`
    ].filter(Boolean).join(' · ');
    const desc = (p.description || '').trim();
    const features = (p.features || '').trim();
    const subParts = [meta];
    if (desc) subParts.push(desc.length > 160 ? desc.slice(0, 157) + '…' : desc);
    if (features) subParts.push(features.length > 120 ? features.slice(0, 117) + '…' : features);
    const sub = subParts.map(s => escHtml(s)).join('<br>');
    return `<label class="select-row pres-pick-row">
      <span class="select-row-text">
        <span class="select-row-title">${escHtml(p.name || 'Untitled')}</span>
        <span class="select-row-sub">${sub}</span>
      </span>
      <span class="pres-pick-aside">
        <input type="checkbox" class="pres-check select-row-check" value="${escHtml(p.id)}" />
        <span class="pres-pick-price">${escHtml(ngnStr)}</span>
      </span>
    </label>`;
  }).join('');
}

function selectAllPres(checked) {
  document.querySelectorAll('#pres-picker .pres-check').forEach(cb => { cb.checked = checked; });
}

function formatNairaPlain(n) {
  const v = Number(n) || 0;
  return 'N' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function loadJsPdf() {
  return new Promise((resolve, reject) => {
    if (window.jspdf && window.jspdf.jsPDF) return resolve(window.jspdf.jsPDF);
    if (window.jsPDF) return resolve(window.jsPDF);
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    s.onload = () => resolve((window.jspdf && window.jspdf.jsPDF) || window.jsPDF);
    s.onerror = () => reject(new Error('Could not load PDF engine. Please connect to the internet once to generate presentations.'));
    document.head.appendChild(s);
  });
}

function generatePresentation() {
  const checked = [...document.querySelectorAll('#pres-picker .pres-check:checked')];
  const quoteItems = window._presQuoteItems || [];
  let products = [];
  if (quoteItems.length) {
    // Prefer quote-loaded items (includes qty + unit price); merge any extra checked products not already included
    const ids = new Set(quoteItems.map(x => x.productId).filter(Boolean));
    products = quoteItems.slice();
    checked.forEach(cb => {
      if (ids.has(cb.value)) return;
      const p = getProduct(cb.value);
      if (p) products.push({ ...p, qty: 1, price: toNGN(p.price, p.currency), currency: 'NGN' });
    });
  } else {
    products = checked.map(cb => {
      const p = getProduct(cb.value);
      if (!p) return null;
      return { ...p, qty: 1, price: toNGN(p.price, p.currency), currency: 'NGN' };
    }).filter(Boolean);
  }
  if (products.length === 0) {
    alert('Select equipment or load a quotation first.');
    return;
  }
  const forClient = document.getElementById('pres-client')?.value.trim() || 'Our Valued Hospital Partner';
  const co = data.company;
  const dateStr = new Date().toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
  const title = document.getElementById('pres-title')?.value.trim() || 'Medical Equipment Proposal';
  const layout = (document.querySelector('input[name="pres-layout"]:checked')?.value) || 'picture';
  const summaryMode = (document.querySelector('input[name="pres-summary"]:checked')?.value) || 'complex';
  const globalMarkup = parseFloat(document.getElementById('pres-global-markup')?.value) || 0;

  const btn = document.querySelector('#page-presentation button[onclick="generatePresentation()"]');
  if (btn) { btn.disabled = true; btn.textContent = 'Generating PDF…'; }

  loadJsPdf().then(JsPDF => {
    buildPresentationPdf(JsPDF, products, co, forClient, dateStr, title, layout, summaryMode, globalMarkup);
  }).catch(err => {
    alert(err.message || 'PDF generation failed.');
  }).finally(() => {
    if (btn) { btn.disabled = false; btn.textContent = 'Generate High-Quality PDF Presentation'; }
  });
}

function buildPresentationPdf(JsPDF, products, co, forClient, dateStr, title, layout, summaryMode, globalMarkup) {
  const doc = new JsPDF({ unit: 'pt', format: 'a4', orientation: 'portrait' });
  const W = doc.internal.pageSize.getWidth();  // 595.28
  const H = doc.internal.pageSize.getHeight(); // 841.89
  const M = 42;
  const NAVY = [11, 22, 38];
  const NAVY2 = [24, 44, 68];
  const GOLD = [196, 162, 96];
  const GOLDSOFT = [214, 190, 140];
  const CREAM = [247, 244, 237];
  const CREAM2 = [238, 233, 222];
  const INK = [30, 30, 32];
  const GRAY = [110, 112, 118];
  const LINE = [222, 216, 202];
  const WHITE = [255, 255, 255];

  const setCol = (rgb) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const setFill = (rgb) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setDraw = (rgb) => doc.setDrawColor(rgb[0], rgb[1], rgb[2]);

  // Standard body size matches T&C body (12.5pt)
  const BODY = 12.5;
  const BODY_LEAD = 16;
  const isList = (layout === 'list' || layout === 'brochure');
  const isSimpleSummary = (summaryMode === 'simple');
  const isUltraSummary = (summaryMode === 'ultra');
  const globalMk = parseFloat(globalMarkup) || 0;

  function wrap(text, fontSize, maxW, font='normal') {
    doc.setFont('helvetica', font);
    doc.setFontSize(fontSize);
    return doc.splitTextToSize(String(text || ''), maxW);
  }

  // Top running header — keep clear of page titles below
  function footer(pageNo, total) {
    setCol(GRAY);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.text((co.name || 'MEDICANO RESOURCES LIMITED').toUpperCase(), M, 22);
    setCol([115, 128, 140]);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(14);
    doc.text(String(pageNo).padStart(2, '0') + ' / ' + String(total).padStart(2, '0'), W - M, 24, { align: 'right' });
  }

  function lineUnitBase(p) {
    return (p.currency === 'NGN' || p.fromQuote) ? (parseFloat(p.price) || 0) : toNGN(p.price, p.currency);
  }
  function lineUnit(p) {
    return lineUnitBase(p) * (1 + globalMk / 100);
  }
  function lineQty(p) {
    return Math.max(1, parseFloat(p.qty) || 1);
  }
  function lineTotal(p) {
    return lineUnit(p) * lineQty(p);
  }

  function estimateCardH(p) {
    if (isList) {
      const nameLines = Math.min(2, Math.max(1, wrap(p.name || '', 10.5, W - 2 * M - 160, 'bold').length));
      const desc = String(p.description || '').trim();
      const descLines = desc ? Math.min(2, wrap(desc, 9, W - 2 * M - 160).length) : 0;
      return Math.max(52, 28 + nameLines * 12 + descLines * 11 + 18);
    }
    const feats = (p.features || '').split('\n').map(f => f.trim()).filter(Boolean).length;
    const descLines = Math.max(1, wrap(p.description || '', BODY, W - 2 * M - 140).length);
    let h = 100 + descLines * BODY_LEAD + Math.max(feats, 0) * (BODY_LEAD - 1) + 28;
    return Math.max(150, Math.min(h + 12, 280));
  }

  function packMachines(list) {
    // More cards when content is short; list mode packs denser
    const usable = isList ? 620 : 560;
    const gap = isList ? 6 : 12;
    const maxPerPage = isList ? 14 : 4;
    const heights = list.map(estimateCardH);
    const packs = [];
    let i = 0;
    while (i < list.length) {
      const items = [];
      let used = 0;
      while (i < list.length) {
        const h = heights[i];
        const need = items.length ? h + gap : h;
        if (items.length && used + need > usable) break;
        items.push({ p: list[i], h, idx: i });
        used += need;
        i++;
        if (items.length >= maxPerPage) break;
      }
      packs.push({ items, usedH: used, gap });
    }
    return packs;
  }

  function drawPictureCard(p, x, y, w, h) {
    setFill(WHITE); setDraw(LINE); doc.setLineWidth(0.75);
    doc.roundedRect(x, y, w, h, 8, 8, 'FD');
    const pad = 14;
    const imgSize = Math.min(118, h - 2 * pad);
    const imgY = y + pad + Math.max(0, (h - 2 * pad - imgSize) / 2);
    setFill(NAVY2); setDraw(GOLD); doc.setLineWidth(1);
    doc.roundedRect(x + pad, imgY, imgSize, imgSize, 4, 4, 'FD');
    if (p.image) {
      try {
        doc.addImage(p.image, 'JPEG', x + pad + 1, imgY + 1, imgSize - 2, imgSize - 2);
      } catch (e) {
        setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(16);
        doc.text('EQ', x + pad + imgSize / 2, imgY + imgSize / 2 + 5, { align: 'center' });
      }
    } else {
      setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(16);
      doc.text('EQ', x + pad + imgSize / 2, imgY + imgSize / 2 + 5, { align: 'center' });
    }
    const tx = x + pad + imgSize + 16;
    const tw = w - (pad + imgSize + 16) - pad;
    let ty = y + pad + 12;
    setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.4);
    doc.text(String(p.category || 'EQUIPMENT').toUpperCase(), tx, ty);
    ty += 16;
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
    wrap(p.name, 13, tw, 'bold').slice(0, 2).forEach(ln => { doc.text(ln, tx, ty); ty += 14; });
    setDraw(LINE); doc.setLineWidth(1); doc.line(tx, ty, tx + 28, ty);
    ty += 14;
    setCol([87, 88, 92]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
    wrap(p.description || '', BODY, tw).slice(0, 4).forEach(ln => { doc.text(ln, tx, ty); ty += BODY_LEAD - 2; });
    ty += 6;
    (p.features || '').split('\n').map(f => f.trim()).filter(Boolean).slice(0, 5).forEach(f => {
      setFill(GOLD); doc.circle(tx + 3, ty - 2, 1.6, 'F');
      setCol([56, 57, 61]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
      doc.text(f.substring(0, 72), tx + 10, ty);
      ty += BODY_LEAD - 1;
    });
    const unitNgn = lineUnit(p);
    const qty = lineQty(p);
    const lineNgn = unitNgn * qty;
    setCol(GRAY); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    doc.text('PRICE', x + w - pad, y + h - pad - 28, { align: 'right' });
    setCol([115, 118, 124]); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    doc.text(formatNairaPlain(unitNgn) + ' × (' + qty + (qty === 1 ? ' unit' : ' units') + ')', x + w - pad, y + h - pad - 16, { align: 'right' });
    setCol(NAVY); doc.setFontSize(BODY); doc.setFont('helvetica', 'bold');
    doc.text(formatNairaPlain(lineNgn), x + w - pad, y + h - pad - 2, { align: 'right' });
  }

  function drawListCard(p, x, y, w, h) {
    setFill(WHITE); setDraw(LINE); doc.setLineWidth(0.55);
    doc.roundedRect(x, y, w, h, 5, 5, 'FD');
    const padX = 12;
    const padY = 10;
    let ty = y + padY + 8;
    setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(6.5);
    doc.text(String(p.category || 'EQUIPMENT').toUpperCase(), x + padX, ty);
    // price block right
    const unitNgn = lineUnit(p);
    const qty = lineQty(p);
    const lineNgn = unitNgn * qty;
    setCol([115, 118, 124]); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.text(formatNairaPlain(unitNgn) + ' × (' + qty + (qty === 1 ? ' unit' : ' units') + ')', x + w - padX, ty, { align: 'right' });
    ty += 12;
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
    const nameMax = w - padX * 2 - 120;
    wrap(p.name || '', 10.5, nameMax, 'bold').slice(0, 2).forEach(ln => { doc.text(ln, x + padX, ty); ty += 12; });
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.text(formatNairaPlain(lineNgn), x + w - padX, y + padY + 22, { align: 'right' });
    const desc = String(p.description || '').trim();
    if (desc) {
      setCol([90, 92, 98]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      wrap(desc, 9, w - padX * 2 - 100).slice(0, 2).forEach(ln => { doc.text(ln, x + padX, ty); ty += 11; });
    }
  }

  function drawCard(p, x, y, w, h) {
    if (isList) drawListCard(p, x, y, w, h);
    else drawPictureCard(p, x, y, w, h);
  }

  // Multi-page pricing summary — continues before footer when long
  function drawSummaryPages(list, startPageNo, totalPagesGuess) {
    const rowH = 28;
    const topY = 122;
    const bottomSafe = 58;
    const maxRowsFirst = Math.floor((H - topY - bottomSafe - 90) / rowH);
    const maxRowsCont = Math.floor((H - topY - bottomSafe - 40) / rowH);
    const chunks = [];
    let i = 0;
    let first = true;
    while (i < list.length) {
      const n = first ? Math.max(1, maxRowsFirst) : Math.max(1, maxRowsCont);
      chunks.push(list.slice(i, i + n));
      i += n;
      first = false;
    }
    if (!chunks.length) chunks.push([]);

    let pageNo = startPageNo;
    const grandTotal = list.reduce((s, p) => s + lineTotal(p), 0);

    chunks.forEach((chunk, ci) => {
      if (ci > 0) doc.addPage();
      setFill(CREAM); doc.rect(0, 0, W, H, 'F');
      setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
      doc.text('INVESTMENT', M, 58);
      setCol(NAVY); doc.setFontSize(22);
      doc.text(ci === 0 ? 'Pricing Summary' : 'Pricing Summary (continued)', M, 86);
      setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 102, M + 54, 102);

      const isLast = ci === chunks.length - 1;
      const panelTop = topY;
      const rowsH = chunk.length * rowH;
      const totalBand = isLast ? 52 : 0;
      const noteH = isLast ? 22 : 0;
      const panelH = 36 + rowsH + 16 + totalBand + noteH + 24;
      const cardW = W - 2 * M;

      setFill(NAVY);
      doc.roundedRect(M, panelTop, cardW, Math.min(panelH, H - panelTop - bottomSafe + 8), 10, 10, 'F');

      setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
      doc.text(ci === 0 ? 'PRICING SUMMARY' : 'CONTINUED', M + 28, panelTop + 28);

      let ry = panelTop + 48;
      chunk.forEach(p => {
        if (ry > H - bottomSafe - (isLast ? 70 : 20)) return;
        setCol(CREAM2); doc.setFont('helvetica', 'normal'); doc.setFontSize(11);
        const qty = lineQty(p);
        const name = String(p.name || '').substring(0, 40) + (qty > 1 ? ' ×' + qty : '');
        doc.text(name, M + 28, ry);
        doc.setFont('helvetica', 'bold');
        doc.text(formatNairaPlain(lineTotal(p)), W - M - 28, ry, { align: 'right' });
        ry += rowH;
      });

      if (isLast) {
        setDraw([80, 100, 120]); doc.setLineWidth(0.9);
        doc.line(M + 28, ry - 6, W - M - 28, ry - 6);
        ry += 18;
        setCol(CREAM); doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
        doc.text('TOTAL PROPOSAL VALUE', M + 28, ry);
        setCol(GOLD); doc.setFontSize(16);
        doc.text(formatNairaPlain(grandTotal), W - M - 28, ry, { align: 'right' });
        ry += 22;
        setCol([160, 170, 185]); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        doc.text('Prices are indicative and exclude installation, freight, and applicable duties.', M + 28, ry);
      } else {
        setCol([160, 170, 185]); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        doc.text('Continued on next page…', M + 28, ry + 4);
      }

      footer(pageNo, totalPagesGuess);
      pageNo++;
    });
    return pageNo;
  }

  // Ultra-simple table summary (image-style: navy header, zebra rows)
  function drawUltraSummaryPages(list, startPageNo, totalPagesGuess, firstTopY) {
    // Item | Qty | Original Unit Price | Line Total — no title; multi-page
    const rowH = 24;
    const headerH = 32;
    const bottomSafe = 48;
    const tableLeft = M;
    const tableW = W - 2 * M;
    const colQtyW = 48;
    const colUnitW = 112;
    const colLineW = 112;
    const colItemW = tableW - colQtyW - colUnitW - colLineW;
    const xItem = tableLeft;
    const xQty = tableLeft + colItemW;
    const xUnit = xQty + colQtyW;
    const xLine = xUnit + colUnitW;

    const topFirst = (firstTopY != null) ? firstTopY : 48;
    const topCont = 48;
    const maxFirst = Math.max(6, Math.floor((H - topFirst - bottomSafe - headerH - 36) / rowH));
    const maxCont = Math.max(12, Math.floor((H - topCont - bottomSafe - headerH - 36) / rowH));

    const chunks = [];
    let i = 0;
    let first = true;
    while (i < list.length) {
      const n = first ? maxFirst : maxCont;
      chunks.push(list.slice(i, i + n));
      i += n;
      first = false;
    }
    if (!chunks.length) chunks.push([]);

    const grandTotal = list.reduce((s, p) => s + lineTotal(p), 0);
    let pageNo = startPageNo;

    function drawTableChunk(chunk, topY, isLast) {
      let ty = topY;
      const tableStartY = ty;

      setFill(NAVY);
      doc.rect(tableLeft, ty, tableW, headerH, 'F');
      setCol(WHITE); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      const hy = ty + 14;
      doc.text('Item', xItem + 10, hy + 6);
      doc.text('Qty', xQty + colQtyW / 2, hy + 6, { align: 'center' });
      doc.text('Original Unit', xUnit + colUnitW - 8, hy, { align: 'right' });
      doc.text('Price', xUnit + colUnitW - 8, hy + 11, { align: 'right' });
      doc.text('Line Total', xLine + colLineW - 8, hy + 6, { align: 'right' });
      ty += headerH;

      chunk.forEach((p, ri) => {
        if (ri % 2 === 1) {
          setFill([242, 244, 247]);
          doc.rect(tableLeft, ty, tableW, rowH, 'F');
        } else {
          setFill(WHITE);
          doc.rect(tableLeft, ty, tableW, rowH, 'F');
        }
        setDraw([210, 215, 222]);
        doc.setLineWidth(0.5);
        doc.line(tableLeft, ty + rowH, tableLeft + tableW, ty + rowH);
        doc.line(xQty, ty, xQty, ty + rowH);
        doc.line(xUnit, ty, xUnit, ty + rowH);
        doc.line(xLine, ty, xLine, ty + rowH);

        const qty = lineQty(p);
        const unit = lineUnit(p);
        const total = unit * qty;
        const name = String(p.name || 'Item');
        setCol([30, 35, 42]); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        const maxNameW = colItemW - 18;
        let displayName = name;
        while (doc.getTextWidth(displayName) > maxNameW && displayName.length > 5) {
          displayName = displayName.slice(0, -2);
        }
        if (displayName !== name) displayName = displayName.replace(/\s+\S*$/, '') + '…';
        const textY = ty + 16;
        doc.text(displayName, xItem + 10, textY);
        doc.text(String(qty), xQty + colQtyW / 2, textY, { align: 'center' });
        doc.text(formatNairaPlain(unit), xUnit + colUnitW - 8, textY, { align: 'right' });
        doc.setFont('helvetica', 'bold');
        doc.text(formatNairaPlain(total), xLine + colLineW - 8, textY, { align: 'right' });
        ty += rowH;
      });

      setDraw([180, 186, 196]);
      doc.setLineWidth(0.8);
      doc.rect(tableLeft, tableStartY, tableW, headerH + chunk.length * rowH);

      if (isLast) {
        ty += 10;
        setFill(NAVY);
        doc.rect(tableLeft, ty, tableW, 28, 'F');
        setCol(WHITE); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
        doc.text('TOTAL', xItem + 10, ty + 18);
        doc.text(formatNairaPlain(grandTotal), xLine + colLineW - 8, ty + 18, { align: 'right' });
      } else {
        setCol([100, 110, 120]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
        doc.text('Continued on next page…', M, ty + 18);
      }
    }

    chunks.forEach((chunk, ci) => {
      if (ci === 0 && firstTopY != null) {
        // First page already started by caller (offer drawn) — only table
        drawTableChunk(chunk, topFirst, ci === chunks.length - 1);
      } else {
        if (!(ci === 0 && firstTopY != null)) {
          if (ci > 0 || firstTopY == null) doc.addPage();
        }
        setFill(CREAM); doc.rect(0, 0, W, H, 'F');
        drawTableChunk(chunk, ci === 0 && firstTopY == null ? topFirst : topCont, ci === chunks.length - 1);
      }
      footer(pageNo, totalPagesGuess);
      pageNo++;
    });
    return pageNo;
  }

  const packs = isUltraSummary ? [] : packMachines(products);
  const estUltraPages = Math.max(1, Math.ceil(products.length / 24));
  const estSummaryPages = isSimpleSummary
    ? 0
    : isUltraSummary
      ? estUltraPages
      : Math.max(1, Math.ceil(products.length / (isList ? 18 : 14)));
  const catPages = packs.length + estSummaryPages;
  const totalPages = 2 + catPages + 2;

  // ---- COVER ----
  // Full-page navy (must fill entire page so nothing sits on white)
  setFill(NAVY); doc.rect(0, 0, W, H, 'F');
  setDraw([56, 77, 102]); doc.setLineWidth(0.75);
  doc.rect(26, 26, W - 52, H - 52);
  const nameParts = (co.name || 'MEDICANO RESOURCES LIMITED').split(/\s+/);
  const main = (nameParts[0] || 'MEDICANO').toUpperCase();
  const sub = (nameParts.slice(1).join(' ') || 'RESOURCES LIMITED').toUpperCase();
  // Centered brand block
  setCol(CREAM); doc.setFont('helvetica', 'bold'); doc.setFontSize(36);
  doc.text(main, W / 2, H * 0.40, { align: 'center' });
  setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(13);
  doc.text(sub, W / 2, H * 0.40 + 24, { align: 'center' });
  setDraw(GOLD); doc.setLineWidth(1.5);
  doc.line(W / 2 - 30, H * 0.40 + 42, W / 2 + 30, H * 0.40 + 42);
  setCol(CREAM); doc.setFontSize(15); doc.text('Medical Equipment Proposal', W / 2, H * 0.40 + 68, { align: 'center' });
  setCol([184, 191, 204]); doc.setFontSize(11.5);
  doc.text('Prepared for ' + forClient, W / 2, H * 0.40 + 92, { align: 'center' });
  doc.text(dateStr, W / 2, H * 0.40 + 110, { align: 'center' });

  // Footer block — measure first, place fully inside navy (above bottom margin)
  const footSize = 9;
  const footLead = 11;
  const addrLines = wrap(co.address || '', footSize, W - 2 * M - 100);
  const telLine = (co.phone1 || co.phone2)
    ? 'Tel: ' + [co.phone1, co.phone2].filter(Boolean).join('  |  ')
    : '';
  const emailLine = co.email ? 'Email: ' + co.email : '';
  const footLines = [...addrLines];
  if (telLine) footLines.push(telLine);
  if (emailLine) footLines.push(emailLine);
  const footBlockH = footLines.length * footLead + 16; // + space under divider
  const footBottom = 48; // stay above page edge
  const dividerY = footBottom + footBlockH;
  setDraw([56, 77, 102]); doc.setLineWidth(0.75);
  doc.line(M, dividerY, W - M, dividerY);
  // Brighter text so it stays readable on navy
  setCol([220, 226, 234]); doc.setFont('helvetica', 'normal'); doc.setFontSize(footSize);
  let by = dividerY + 14;
  footLines.forEach(ln => {
    doc.text(ln, M, by);
    by += footLead;
  });
  setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(16);
  doc.text('01 / ' + String(totalPages).padStart(2, '0'), W - M, footBottom + 4, { align: 'right' });

  // ---- ABOUT ----
  doc.addPage();
  setFill(CREAM); doc.rect(0, 0, W, H, 'F');
  const panelW = 170;
  setFill(NAVY); doc.rect(W - panelW, 0, panelW, H, 'F');
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('PRECISION', W - panelW + 18, 90);
  setCol(CREAM2); doc.setFontSize(10);
  doc.text('EQUIPMENT, BUILT', W - panelW + 18, 110);
  doc.text('FOR AFRICAN', W - panelW + 18, 128);
  doc.text('HEALTHCARE.', W - panelW + 18, 146);
  // No phone/email at bottom-right — contact is only in the cards below

  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
  doc.text('COMPANY PROFILE', M, 58);
  setCol(NAVY); doc.setFontSize(20);
  doc.text('WELCOME TO MEDICANO', M, 88);
  doc.text('RESOURCES', M, 112);
  setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 128, M + 54, 128);
  const welcome = "Incorporated in 2010, we are a multispecialty leading player in the marketing and distribution of Turnkey Medical Equipment and Technology in the Nigerian market with core expertise in Endoscopic equipment, Ear, Nose and Throat Equipment, Cranio and Oral Maxillofacial, Imaging Equipment (MRI, CT, X-Ray, Ultrasound etc), Hospital Furnishing, Intensive Care Unit Solutions, Neonatal & Pediatrics' solutions as well as a wide Theatre instruments portfolio and equipment amongst other things.\n\nWe offer complete integrated medical solutions to our clients which has endeared us to their hearts. We say integrated because we proffer advisory services, through our seasoned and well trained technical personnel, from our first contact with the client all the way to our after sales service long after the sales have been made. Also, our tradition of excellent service delivery by our experienced and enthusiastic employees, has continued to differentiate us from others in the health care industry.";
  setCol([55, 56, 60]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
  let ay = 152;
  const maxAboutW = W - panelW - M - 28;
  welcome.split('\n').forEach(para => {
    if (!para.trim()) { ay += 10; return; }
    wrap(para.trim(), BODY, maxAboutW).forEach(ln => { doc.text(ln, M, ay); ay += BODY_LEAD; });
    ay += 8;
  });
  // Detail cards: address / phone / email
  ay += 16;
  const cardGap = 12;
  const leftW = W - panelW - M - 28;
  const cardW3 = (leftW - cardGap * 2) / 3;
  const cardH = 150;
  const cards = [
    ['REGISTERED OFFICE', co.address || '', 'text'],
    ['DIRECT LINE', [co.phone1, co.phone2].filter(Boolean).join('\n'), 'text'],
    ['CORRESPONDENCE', co.email || '', 'email']
  ];
  cards.forEach((card, i) => {
    const cx = M + i * (cardW3 + cardGap);
    setFill(WHITE); setDraw(LINE); doc.setLineWidth(0.75);
    doc.roundedRect(cx, ay, cardW3, cardH, 6, 6, 'FD');
    // Gold accent with clear space before the label and address
    setDraw(GOLD); doc.setLineWidth(1.6); doc.line(cx + 12, ay + 18, cx + 34, ay + 18);
    setCol(GRAY); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    doc.text(card[0], cx + 12, ay + 40);
    setCol(NAVY); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
    let vy = ay + 60;
    const maxTextW = cardW3 - 24;
    if (card[2] === 'email' && card[1]) {
      const email = String(card[1]).trim();
      const lines = wrap(email, BODY, maxTextW);
      lines.forEach((ln, li) => {
        // Clickable mailto link (jsPDF)
        try {
          if (typeof doc.textWithLink === 'function') {
            setCol([11, 90, 160]);
            doc.textWithLink(ln, cx + 12, vy, { url: 'mailto:' + email });
          } else {
            setCol([11, 90, 160]);
            doc.text(ln, cx + 12, vy);
            const tw = doc.getTextWidth(ln);
            doc.link(cx + 12, vy - BODY + 2, tw, BODY + 2, { url: 'mailto:' + email });
          }
        } catch (e) {
          setCol([11, 90, 160]);
          doc.text(ln, cx + 12, vy);
        }
        // Underline to show it is a link
        setDraw([11, 90, 160]); doc.setLineWidth(0.6);
        const tw2 = doc.getTextWidth(ln);
        doc.line(cx + 12, vy + 2, cx + 12 + tw2, vy + 2);
        vy += BODY_LEAD - 2;
      });
    } else {
      wrap(card[1], BODY, maxTextW).slice(0, 6).forEach(ln => {
        doc.text(ln, cx + 12, vy); vy += BODY_LEAD - 2;
      });
    }
  });
  // Tagline after contact cards, before page footer
  const tagY = Math.min(ay + cardH + 28, H - 56);
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
  doc.text('...Making a Habit of Excellence', M, tagY);
  footer(2, totalPages);

  // ---- CATALOGUE / ULTRA TABLE ----
  let pageNo = 3;
  function drawSimpleTotal(x, y, w) {
    const grand = products.reduce((s, p) => s + lineTotal(p), 0);
    const boxH = 72;
    setFill(NAVY);
    doc.roundedRect(x, y, w, boxH, 10, 10, 'F');
    setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    doc.text('TOTAL PROPOSAL VALUE', x + 20, y + 26);
    setCol(CREAM); doc.setFont('helvetica', 'bold'); doc.setFontSize(18);
    doc.text(formatNairaPlain(grand), x + w - 20, y + 30, { align: 'right' });
    setCol([160, 170, 185]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    doc.text(products.length + (products.length === 1 ? ' item' : ' items') + ' · indicative pricing in Naira', x + 20, y + 52);
    return boxH;
  }

  const offerText = 'Please find below herewith our OFFER for equipping your hospital with our PREMIUM MEDICAL EQUIPMENT that assures of quality and long-lasting use. We look forward to your final review to enable us proceed on the arrangement.';

  if (isUltraSummary) {
    // Ultra: offer text, then table only (no catalogue cards, no "Price Summary" heading)
    doc.addPage();
    setFill(CREAM); doc.rect(0, 0, W, H, 'F');
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
    doc.text('Equipment Catalogue', M, 58);
    setDraw(GOLD); doc.setLineWidth(1.4); doc.line(M, 74, M + 54, 74);
    setCol([55, 56, 60]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
    let oy = 74 + 20;
    wrap(offerText, BODY, W - 2 * M).forEach(ln => { doc.text(ln, M, oy); oy += BODY_LEAD; });
    const tableTop = oy + 18;
    pageNo = drawUltraSummaryPages(products, pageNo, totalPages, tableTop);
  } else {
    packs.forEach((pack, pi) => {
      doc.addPage();
      setFill(CREAM); doc.rect(0, 0, W, H, 'F');
      setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
      doc.text('Equipment Catalogue', M, 58);
      let topLimit = 100;
      if (pi > 0) {
        setCol(GRAY); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
        doc.text('continued', W - M, 58, { align: 'right' });
        setDraw(GOLD); doc.setLineWidth(1.4); doc.line(M, 74, M + 54, 74);
        topLimit = 92;
      } else {
        setDraw(GOLD); doc.setLineWidth(1.4); doc.line(M, 74, M + 54, 74);
        setCol([55, 56, 60]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
        let oy = 74 + 20;
        wrap(offerText, BODY, W - 2 * M).forEach(ln => { doc.text(ln, M, oy); oy += BODY_LEAD; });
        topLimit = oy + 18;
      }

      const gap = pack.gap != null ? pack.gap : (isList ? 6 : 12);
      const isLastPack = pi === packs.length - 1;
      const simpleBoxH = 72;
      const simpleGap = 16;
      const reserveSimple = (isSimpleSummary && isLastPack) ? (simpleBoxH + simpleGap) : 0;
      const totalH = pack.items.reduce((s, it) => s + it.h, 0) + gap * Math.max(0, pack.items.length - 1);
      const bottomLimit = 50 + reserveSimple;
      const area = H - topLimit - bottomLimit;
      let yTop = topLimit + Math.max(0, (area - totalH) / 2);
      if (isList && pack.items.length >= 8) yTop = topLimit;
      if (reserveSimple && yTop + totalH + simpleGap + simpleBoxH > H - 50) {
        yTop = topLimit;
      }
      const cardW = W - 2 * M;
      pack.items.forEach(it => {
        drawCard(it.p, M, yTop, cardW, it.h);
        yTop += it.h + gap;
      });
      if (isSimpleSummary && isLastPack) {
        let sy = yTop + simpleGap;
        if (sy + simpleBoxH > H - 48) {
          sy = Math.max(topLimit, H - 48 - simpleBoxH);
        }
        drawSimpleTotal(M, sy, cardW);
      }
      footer(pageNo, totalPages);
      pageNo++;
    });

    if (!isSimpleSummary) {
      doc.addPage();
      pageNo = drawSummaryPages(products, pageNo, totalPages);
    }
  }

  // ---- TERMS (always ONE page — auto-fit spacing so nothing spills) ----
  let termHeadSize = 14;
  let termBodySize = 12.5;
  let termBodyLead = 17;
  let termGap = 16;
  let termHeadLead = 18;
  const termsList = (data.terms && data.terms.length) ? data.terms : DEFAULT_DATA.terms;

  function measureTermsBlock(list, bodySize, bodyLead, headLead, gap) {
    let h = 0;
    list.forEach((t) => {
      const val = t.body || t[1] || '';
      h += headLead;
      h += wrap(val, bodySize, W - 2 * M).length * bodyLead;
      h += gap;
    });
    return h;
  }

  doc.addPage();
  setFill(CREAM); doc.rect(0, 0, W, H, 'F');
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text('COMMERCIAL TERMS', M, 58);
  setCol(NAVY); doc.setFontSize(22);
  doc.text('Terms and Conditions', M, 86);
  setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 102, M + 54, 102);

  const usableTop = 122;
  const usableBottom = H - 48;
  const usableH = usableBottom - usableTop;

  let blockH = measureTermsBlock(termsList, termBodySize, termBodyLead, termHeadLead, termGap);
  let guard = 0;
  while (blockH > usableH && guard < 14) {
    termBodyLead = Math.max(13, termBodyLead - 0.5);
    termGap = Math.max(7, termGap - 0.8);
    termHeadLead = Math.max(14, termHeadLead - 0.4);
    if (guard > 5) {
      termBodySize = Math.max(10.5, termBodySize - 0.25);
      termHeadSize = Math.max(12, termHeadSize - 0.25);
    }
    blockH = measureTermsBlock(termsList, termBodySize, termBodyLead, termHeadLead, termGap);
    guard++;
  }

  // Vertically center the full T&C group on this single page
  let ty = usableTop + Math.max(0, (usableH - blockH) / 2);

  termsList.forEach((t) => {
    const lab = t.title || t[0] || '';
    const val = t.body || t[1] || '';
    const lines = wrap(val, termBodySize, W - 2 * M);
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(termHeadSize);
    doc.text(String(lab).toUpperCase(), M, ty); ty += termHeadLead;
    setCol([50, 51, 55]); doc.setFont('helvetica', 'normal'); doc.setFontSize(termBodySize);
    lines.forEach(ln => { doc.text(ln, M, ty); ty += termBodyLead; });
    ty += termGap;
  });
  footer(pageNo, totalPages);
  pageNo++;

  // ---- CLOSING (same font units as T&C) ----
  doc.addPage();
  setFill(CREAM); doc.rect(0, 0, W, H, 'F');
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text('NEXT STEPS', M, 58);
  setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 74, M + 54, 74);

  // Measure closing block then center vertically
  const closeLines1 = wrap('Thank you for doing business with us while we look forward to receiving the confirmation of your order.', termBodySize, W - 2 * M - 40);
  const closeLines2 = wrap('For further information or any clarification, please contact us the undersigned on Tel. 09099995426 or call Francis on 08023203522. E-mail: enquiries@medicanoresources.com', termBodySize, W - 2 * M - 40);
  const closeBlockH = closeLines1.length * termBodyLead + 14 + closeLines2.length * termBodyLead + 28 + termBodyLead + 36 + termHeadLead + 40 + termBodyLead;
  let cy = 96 + Math.max(0, (H - 96 - 50 - closeBlockH) / 2);

  setCol(INK); doc.setFont('helvetica', 'normal'); doc.setFontSize(termBodySize);
  closeLines1.forEach(ln => { doc.text(ln, M, cy); cy += termBodyLead; });
  cy += 14;
  closeLines2.forEach(ln => { doc.text(ln, M, cy); cy += termBodyLead; });
  cy += 28;
  doc.setFontSize(termBodySize); doc.text('Yours faithfully,', M, cy);
  cy += 36;
  setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(termHeadSize);
  doc.text('FOR: ' + (co.name || 'Medicano Resources Limited'), M, cy);
  cy += 40;
  doc.setFontSize(termHeadSize); doc.text('Francis Opara', M, cy);
  setCol(GRAY); doc.setFont('helvetica', 'normal'); doc.setFontSize(termBodySize);
  doc.text('CEO', M, cy + 18);
  footer(pageNo, totalPages);

  // Filename leads with client/hospital name
  const sanitize = (s, max) => String(s || '')
    .replace(/[\\/:*?"<>|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max || 50);
  const clientName = sanitize(forClient, 50) || 'Client';
  const docTitle = sanitize(title, 40) || 'Presentation';
  doc.save(clientName + ' - ' + docTitle + '.pdf');
}

function escHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// -------------------- Dark Mode --------------------
function toggleDarkMode() {
  const html = document.documentElement;
  const isDark = html.classList.toggle('dark');
  localStorage.setItem('medicano_dark', isDark ? '1' : '0');
  const btn = document.getElementById('dark-toggle');
  if (btn) btn.textContent = isDark ? '☀️' : '🌙';
}

function initDarkMode() {
  const saved = localStorage.getItem('medicano_dark');
  if (saved === '1' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
    document.documentElement.classList.add('dark');
    const btn = document.getElementById('dark-toggle');
    if (btn) btn.textContent = '☀️';
  }
}

// -------------------- Quote Product Picker --------------------
function toggleQuoteEquipPanel() {
  const panel = document.getElementById('quote-equip-panel');
  if (!panel) return;
  panel.classList.toggle('collapsed');
}

function renderQuoteProductPicker() {
  const search = (document.getElementById('quote-product-search')?.value || '').toLowerCase();
  const container = document.getElementById('quote-product-picker');
  if (!container) return;

  const active = data.products.filter(p => p.active);
  const list = active.filter(p =>
    !search ||
    p.name.toLowerCase().includes(search) ||
    p.sku.toLowerCase().includes(search) ||
    (p.category || '').toLowerCase().includes(search) ||
    (p.brand || '').toLowerCase().includes(search)
  );

  if (list.length === 0) {
    container.innerHTML = '<p class="p-3 text-slate-400 text-center">No equipment found</p>';
    return;
  }

  container.innerHTML = list.map(p => {
    const ngn = toNGN(p.price, p.currency);
    const desc = (p.description || '').trim();
    const shortDesc = desc ? (desc.length > 90 ? desc.slice(0, 87) + '…' : desc) : '';
    return `<div class="qp-row">
      <input type="checkbox" class="qp-check rounded" value="${p.id}" data-sku="${escHtml(p.sku)}" />
      <div class="qp-meta">
        <p class="font-medium">${escHtml(p.name)}</p>
        <p class="text-xs text-slate-500">${escHtml(p.sku)} • ${escHtml(p.category || '')} • ${formatNGN(ngn)}</p>
        ${shortDesc ? `<p class="text-xs text-slate-400 mt-0.5">${escHtml(shortDesc)}</p>` : ''}
      </div>
      <div class="qp-units">
        <span class="text-xs text-slate-400">Units</span>
        <input type="number" min="1" step="1" value="1" class="qp-qty" data-for="${p.id}" onclick="event.stopPropagation()" />
      </div>
    </div>`;
  }).join('');
}

function selectAllQuoteProducts(checked) {
  document.querySelectorAll('#quote-product-picker .qp-check').forEach(cb => {
    cb.checked = checked;
  });
}

function addSelectedProductsToQuote() {
  const checked = [...document.querySelectorAll('#quote-product-picker .qp-check:checked')];
  if (checked.length === 0) {
    alert('Please select at least one equipment item.');
    return;
  }

  // Map existing product rows to update qty instead of skipping
  const existingRows = {};
  document.querySelectorAll('#quote-items-list .line-card').forEach(row => {
    const sel = row.querySelector('.qi-product');
    if (sel && sel.value) existingRows[sel.value] = row;
  });

  let added = 0;
  let updated = 0;
  checked.forEach(cb => {
    const id = cb.value;
    const qtyInput = document.querySelector('#quote-product-picker .qp-qty[data-for="' + id + '"]');
    const qty = Math.max(1, parseFloat(qtyInput && qtyInput.value) || 1);
    if (existingRows[id]) {
      const qEl = existingRows[id].querySelector('.qi-qty');
      if (qEl) qEl.value = qty;
      updated++;
    } else {
      addQuoteItemRow({ productId: id, qty: qty });
      added++;
    }
  });

  selectAllQuoteProducts(false);
  if (document.getElementById('quote-product-search')) {
    document.getElementById('quote-product-search').value = '';
    renderQuoteProductPicker();
  }

  recalcQuote();
  // Collapse picker after adding so user focuses on units in line items
  const panel = document.getElementById('quote-equip-panel');
  if (panel && (added || updated)) panel.classList.add('collapsed');

  if (!added && !updated) {
    alert('Nothing was added.');
  } else {
    const msg = [];
    if (added) msg.push(added + ' added');
    if (updated) msg.push(updated + ' qty updated');
    // soft feedback via item count is enough
  }
}

